    float* As = smem;                        // BLOCK_ROWS * KT
    float* Bs = smem + BLOCK_ROWS * KT;       // KT * BS_STRIDE (padded to avoid bank conflicts)
    int block_row0 = blockIdx.x * BLOCK_ROWS;
    int block_col0 = blockIdx.y * BLOCK_COLS;
