}
torch::Tensor matmul_tall_skinny_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    A = A.contiguous();
    B = B.contiguous();
    int M = A.size(0);
    int K = A.size(1);
    int M2 = B.size(1);
    TORCH_CHECK(B.size(0) == K, "Inner dimensions must match");
    TORCH_CHECK(M2 == M, "Output must be square (M x M) for this optimized kernel");
    TORCH_CHECK(K % 4 == 0, "K must be a multiple of 4 for vectorized loads");
    auto C = torch::empty({M, M}, A.options());
    dim3 block(THREADS_PER_BLOCK);
    dim3 grid((M + BLOCK_ROWS - 1) / BLOCK_ROWS, (M + BLOCK_COLS - 1) / BLOCK_COLS);
    if (K == 32) {
        size_t shared_mem_size = (size_t)(BLOCK_ROWS * K + K * BS_STRIDE) * sizeof(float);
        if (shared_mem_size > 48 * 1024) {
            cudaFuncSetAttribute(matmul_tall_skinny_kernel_tpl<32>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)shared_mem_size);
        }
        matmul_tall_skinny_kernel_tpl<32><<<grid, block, shared_mem_size>>>(
            A.data_ptr<float>(),
            B.data_ptr<float>(),
            C.data_ptr<float>(),
            M
        );
    } else {
        size_t shared_mem_size = (size_t)(BLOCK_ROWS * K + K * BS_STRIDE) * sizeof(float);
        if (shared_mem_size > 48 * 1024) {
            cudaFuncSetAttribute(matmul_tall_skinny_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)shared_mem_size);
        }
        matmul_tall_skinny_kernel<<<grid, block, shared_mem_size>>>(
            A.data_ptr<float>(),
            B.data_ptr<float>(),
            C.data_ptr<float>(),
            M,
            K
        );
    }
    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "CUDA kernel launch failed: ", cudaGetErrorString(err));
    return C;
